import { NextResponse } from 'next/server';
import { currentUser } from '@clerk/nextjs/server';
import { connect, getConnectionStatus } from '../../../lib/mongodb/mongoose';
import AudioAnalysis from '../../../lib/models/audioAnalysis.model';
import mongoose from 'mongoose';

/**
 * GET handler for fetching a single practice session by ID
 */
export async function GET(request, { params }) {
  try {
    console.log(`API: Fetching practice session with ID: ${params.id}`);

    // Get the current user from Clerk
    const user = await currentUser();
    if (!user) {
      console.log('API: Authentication required - no user found');
      return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
    }

    const userId = user.id;
    const sessionId = params.id;
    console.log(`API: User ID: ${userId}, Session ID: ${sessionId}`);

    // Validate the session ID
    if (!sessionId) {
      console.log('API: Session ID is missing');
      return NextResponse.json({ error: 'Session ID is required' }, { status: 400 });
    }

    // Check if the ID is a valid MongoDB ObjectId
    let isValidObjectId = false;
    try {
      isValidObjectId = mongoose.Types.ObjectId.isValid(sessionId);
      console.log(`API: ObjectId validation result: ${isValidObjectId}`);
    } catch (validationError) {
      console.error('API: Error validating ObjectId:', validationError);
      return NextResponse.json({
        error: 'Invalid session ID format',
        details: validationError.message
      }, { status: 400 });
    }

    if (!isValidObjectId) {
      console.log(`API: Invalid session ID format: ${sessionId}`);
      return NextResponse.json({
        error: 'Invalid session ID format',
        details: 'The provided ID is not a valid MongoDB ObjectId'
      }, { status: 400 });
    }

    // Connect to MongoDB
    console.log('API: Connecting to MongoDB...');
    try {
      await connect();
      console.log(`API: MongoDB connection status: ${getConnectionStatus()}`);
    } catch (dbError) {
      console.error('API: MongoDB connection error:', dbError);
      return NextResponse.json({
        error: 'Database connection error',
        details: dbError.message
      }, { status: 500 });
    }

    // Fetch the practice session by ID and ensure it belongs to the current user
    console.log(`API: Querying for session with _id: ${sessionId} and clerkId: ${userId}`);
    let session;
    try {
      session = await AudioAnalysis.findOne({
        _id: sessionId,
        clerkId: userId
      });
    } catch (queryError) {
      console.error('API: Error querying database:', queryError);
      return NextResponse.json({
        error: 'Database query error',
        details: queryError.message
      }, { status: 500 });
    }

    // If no session is found or it doesn't belong to the user
    if (!session) {
      console.log('API: Practice session not found');
      return NextResponse.json({
        error: 'Practice session not found',
        details: 'The requested practice session does not exist or does not belong to the current user'
      }, { status: 404 });
    }

    console.log('API: Practice session found successfully');

    try {
      // Format date
      console.log('API: Formatting date and time');
      const analysisDate = new Date(session.analysisDate || session.createdAt);
      const formattedDate = analysisDate.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      });

      // Format time
      const formattedTime = analysisDate.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
      });

      // Calculate duration in minutes and seconds
      console.log('API: Calculating duration');
      const durationSeconds = session.voiceAnalysis?.duration || 0;
      const minutes = Math.floor(durationSeconds / 60);
      const seconds = Math.floor(durationSeconds % 60);
      const formattedDuration = `${minutes}:${seconds.toString().padStart(2, '0')}`;

      // Get overall score
      console.log('API: Getting overall score');
      const overallScore = session.recommendations?.performance_assessment?.overall_score || 0;

      // Prepare response data
      console.log('API: Preparing response data');
      const responseData = {
        id: session._id.toString(),
        title: session.fileName || `Practice Session ${formattedDate}`,
        date: formattedDate,
        time: formattedTime,
        timestamp: analysisDate.getTime(),
        duration: formattedDuration,
        durationSeconds: durationSeconds,
        score: Math.round(overallScore),
        // Include the full analysis data
        transcription: session.transcription,
        transcriptAnalysis: session.transcriptAnalysis,
        voiceAnalysis: session.voiceAnalysis,
        textAnalysis: session.textAnalysis,
        recommendations: session.recommendations,
        // Include flags for checking if each analysis section exists
        hasTranscript: !!session.transcription,
        hasVoiceAnalysis: !!session.voiceAnalysis,
        hasTextAnalysis: !!session.textAnalysis,
        hasRecommendations: !!session.recommendations
      };

      console.log('API: Sending successful response');
      return NextResponse.json(responseData, { status: 200 });
    } catch (formattingError) {
      console.error('API: Error formatting practice session data:', formattingError);
      return NextResponse.json({
        error: 'Failed to format practice session data',
        details: formattingError.message
      }, { status: 500 });
    }
  } catch (error) {
    console.error('API: Error fetching practice session:', error);
    return NextResponse.json({
      error: 'Failed to fetch practice session',
      details: error.message
    }, { status: 500 });
  }
}
